<script setup lang="ts">
import {money} from '#shared/utils/pricing'
const db=useDb(),w=useWorkspace(),search=ref(''),{error,busy,run}=useAction()
const {data,refresh}=await useAsyncData('quotes',async()=>check(await db.from('quolyn_quotes').select('*,quolyn_customers(name)').eq('workspace_id',w.value!.id).order('updated_at',{ascending:false})))
const rows=computed(()=>data.value?.filter(q=>(q.number+' '+q.quolyn_customers?.name).toLowerCase().includes(search.value.toLowerCase())))
async function create(){await run(async()=>{const id=check(await db.rpc('save_quote',{w:w.value!.id,p:{request_id:crypto.randomUUID(),lines:[]}}));await navigateTo('/quotes/'+id)})}
</script>
<template><div><div class="page-title"><div><div class="eyebrow">COMMERCIAL DETAILS, CHECKED</div><h1>Quotes</h1><p>Prepare, review and keep a clear record of every revision.</p></div><button class="primary" :disabled="busy" @click="create">＋ New quote</button></div><p v-if="error" class="alert error">{{error}}</p><div class="toolbar"><input v-model="search" aria-label="Search quotes" placeholder="Search quote number or customer…"></div><div class="table-wrap"><table v-if="rows?.length"><thead><tr><th>QUOTE</th><th>CUSTOMER</th><th>STATUS</th><th>TOTAL</th><th>ISSUED / EXPIRES</th></tr></thead><tbody><tr v-for="q in rows" :key="q.id"><td><NuxtLink :to="'/quotes/'+q.id" class="table-link">{{q.number}}</NuxtLink><small>Revision {{q.revision}}</small></td><td>{{q.quolyn_customers?.name||'Not assigned'}}</td><td><span class="pill" :class="q.status">{{q.status}}</span></td><td>{{money(q.total_minor,q.currency)}}</td><td>{{q.issue_date}}<small>{{q.expiry_date}}</small></td></tr></tbody></table><div v-else class="empty"><div class="empty-icon">▤</div><h3>Your first quotation is ahead.</h3><p>Start from a reviewed enquiry or create a draft manually.</p><NuxtLink to="/enquiries" class="secondary">Go to enquiries →</NuxtLink></div></div></div></template>
